import math
# 검색 후 구매 전환율 p 에서 상대 lift 를 가리려면 군마다 몇 명이 필요한가 (양측 5%, 검정력 80%)
z_a, z_b = 1.96, 0.8416
def n_per_arm(p, rel_lift):
    d = p * rel_lift
    return math.ceil(2 * (z_a + z_b) ** 2 * p * (1 - p) / d ** 2)
for p in (0.05, 0.10):
    for lift in (0.01, 0.02, 0.05):
        print(f"전환율 {p:.0%} · 상대 {lift:.0%} 차이 → 군마다 {n_per_arm(p, lift):>12,}명")

# 100일짜리 실험에서 하루 데이터가 잘못돼 다시 계산할 때 읽는 '하루치 묶음' 수
D = 100
def incremental(bad):      # 어제 누적 + 오늘. 고치려면 bad 날부터 끝까지 한 줄로(순서대로)
    steps = D - bad + 1
    return steps * 2, steps            # 읽는 묶음 수, 순서대로 기다려야 하는 단계 수
def full(bad):             # 날마다 첫날부터 전부 다시 읽는다. 날짜끼리는 따로(병렬)
    return sum(d for d in range(bad, D + 1)), 1
def with_state(bad):       # 마지막으로 맞았던 누적(bad-1) + 그 뒤 날들. 날짜끼리는 병렬
    return sum((d - bad + 1) + 1 for d in range(bad, D + 1)), 1
for bad in (1, 95):
    for name, f in [("증분(어제 누적+오늘)", incremental), ("매번 전체", full), ("상태 저장", with_state)]:
        reads, serial = f(bad)
        print(f"{bad:>3}일째가 틀림 | {name:12} | 읽는 묶음 {reads:>5} | 순서대로 {serial:>3}단계")

import math
# 검색어 '노트북' 결과 5개의 관련도(0~3, 사람이 매긴 등급)
def dcg(rels):
    return sum((2 ** r - 1) / math.log2(i + 2) for i, r in enumerate(rels))
def ndcg(rels):
    return dcg(rels) / dcg(sorted(rels, reverse=True))

old = [1, 3, 0, 2, 3]   # 지금 순위
new = [3, 3, 1, 2, 0]   # 새 모델 순위 (같은 상품, 순서만 다름)
print(f"지금 순위 NDCG@5 = {ndcg(old):.3f}")
print(f"새 순위  NDCG@5 = {ndcg(new):.3f}")
# 1위와 5위를 바꾸는 것은 4위와 5위를 바꾸는 것보다 점수가 훨씬 크게 움직인다
print(f"1위 할인 {1/math.log2(2):.2f} · 5위 할인 {1/math.log2(6):.2f}")
